//! 🧪️ Complete MeasureValue controls preserve exact carriers and actual coordinate WHERE authority.
use super::*;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-measure-select-input.json")).unwrap()}
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"integer"=>IfcValue::Integer(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed original vector")}}
fn source(law:&serde_json::Value)->Arc<IfcSnapshot>{Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|row|IfcEntity{id:row["id"].as_str().unwrap().parse().unwrap(),name:row["name"].as_str().unwrap().into(),args:row["args"].as_array().unwrap().iter().map(value).collect(),complex:row["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(value).collect()}).collect()}).collect(),..Default::default()})}
fn payload(row:&serde_json::Value)->serde_json::Value{serde_json::json!({"kind":"typedValue","value":{"name":row["member"],"items":row["items"]}})}
fn event(law:&serde_json::Value,row:&serde_json::Value)->editing::SnapshotEditEvent{editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":law["entity"],"$ifcInputs":if row["items"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":"0","value":payload(row)},{"index":"1","value":payload(row)}])}}))}}
#[test]
fn original_measure_kind_resolves_every_member_and_fixed_array_without_heap_or_filtering(){
 use super::super::super::type_input_kind::{Cursor,Kind};if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let attribute=DetailsTestProfile::normalization_attribute("IFCRIGIDOPERATION",0,true).unwrap().unwrap();let mut cursor=Cursor::default();let mut complete=None;for _ in 0..4096{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>(attribute.type_expr));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(kind)=answer.unwrap(){complete=Some(kind);break;}}assert_eq!(complete,Some(Kind::Select));for(name,expected)in[("IFCCOUNTMEASURE",Kind::Integer),("IFCNUMERICMEASURE",Kind::Number),("IFCCOMPLEXNUMBER",Kind::Array)]{let expression=DetailsTestProfile::defined_type_expression(name).unwrap();let mut cursor=Cursor::default();let mut complete=None;for _ in 0..64{if let Some(kind)=cursor.advance_selected::<DetailsTestProfile>(expression).unwrap(){complete=Some(kind);break;}}assert_eq!(complete,Some(expected));}}
#[test]
fn original_measure_candidates_use_minimal_central_coordinate_atoms_and_exact_inverse(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law);let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(&law,row),&mut caller,&mut work,|input,caller,work|{let mut result=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{result=Some(Ok(emit));break;},Err(error)=>{result=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let result=result.unwrap();assert_eq!(result.is_ok(),row["ready"].as_bool().unwrap(),"{}",row["id"]);if let Ok(emit)=result{assert_eq!(emit.artifact_mutations.len(),2);assert!(emit.artifact_mutations.iter().all(|mutation|matches!(mutation,IfcMutation::SetEntityArg(_))));let mut next=(*snapshot).clone();let mut inverse=Vec::new();for mutation in emit.artifact_mutations{let mut undo=mutation.inverse(&next).unwrap();undo.append(&mut inverse);inverse=undo;next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args[..2],&[value(&payload(row)),value(&payload(row))]));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));}super::constituent_optional_shape_tests::close_with_denials(caller,work);});caller.finish();}}

#[test]
fn original_donated_measure_controls_keep_all_members_exact_numeric_arms_and_array_bindings_under_denied_axes(){
 use semio_framework_plugin::{action_staging::*,app::staged_form::*};
 type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){
  let snapshot=source(&law);let editing::SnapshotEditEvent::SetValue{path,value}=event(&law,row)else{unreachable!()};let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"original-measure".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:None});let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());
  for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();let(repeated,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||guide.as_ref().unwrap().demands());assert_eq!(repeated.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}
  assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert_eq!(prepared.status().ready,row["ready"].as_bool().unwrap(),"{}",row["id"]);let mut offset=0;
  for coordinate in 0..2{let control=prepared.control(offset).unwrap();let StagedScalarKind::Choice{value,choices}=control.scalar.kind else{panic!("all released MeasureValue members")};assert_eq!(choices.iter().map(|choice|choice.key).collect::<Vec<_>>(),law["members"].as_array().unwrap().iter().map(|name|name.as_str().unwrap()).collect::<Vec<_>>());assert_eq!(value,if row["items"].is_null(){""}else{row["member"].as_str().unwrap()});offset+=1;if row["items"].is_null(){continue;}
   let selected=payload(row);let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("original member binding")};let word=DslValue::String(row["member"].as_str().unwrap().into());let StagedFormBorrowedEdit::Set{value,..}=binding.plan(prepared.status(),Some(&word)).unwrap().last().unwrap()else{panic!("original typed constructor")};assert_eq!(value,&super::type_input_tests::raw(&selected));
   let items=row["items"].as_array().unwrap();let control=prepared.control(offset).unwrap();let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("original child binding")};
   if row["member"]=="IFCNUMERICMEASURE"{let StagedScalarKind::Choice{value,choices}=control.scalar.kind else{panic!("explicit NUMBER representation")};assert_eq!(choices.iter().map(|choice|choice.key).collect::<Vec<_>>(),["integer","real"]);assert_eq!(value,items.first().map_or("",|child|child["kind"].as_str().unwrap()));for mode in ["integer","real"]{let selected=DslValue::String(mode.into());let edit=binding.plan(prepared.status(),Some(&selected)).unwrap().last().unwrap();let(path,value)=match edit{StagedFormBorrowedEdit::Append{path,value}if items.is_empty()=>(path,value),StagedFormBorrowedEdit::Set{path,value}if !items.is_empty()=>(path,value),_=>panic!("exact empty-vs-existing NUMBER binding")};assert_eq!(path.len(),if items.is_empty(){6}else{7});assert_eq!(value.get("kind").and_then(DslValue::as_str),Some(mode));let raw=if mode=="real"{value.get("value").unwrap().get("bits").unwrap().as_str().unwrap()}else{value.get("value").unwrap().as_str().unwrap()};assert_eq!(raw,if items.first().is_some_and(|child|child["kind"]==mode){if mode=="real"{items[0]["value"]["bits"].as_str().unwrap()}else{items[0]["value"].as_str().unwrap()}}else{""});}offset+=1;if !items.is_empty(){let control=prepared.control(offset).unwrap();assert!(matches!(control.scalar.kind,StagedScalarKind::Text{..}));offset+=1;}}
   else if row["member"]=="IFCCOMPLEXNUMBER"{assert!(matches!(control.scalar.kind,StagedScalarKind::Button{page:false}));let StagedFormBorrowedEdit::Append{path,value}=binding.plan(prepared.status(),None).unwrap().last().unwrap()else{panic!("explicit ARRAY operation")};assert_eq!(path.len(),if items.is_empty(){6}else{8});assert_eq!(value.get("kind").and_then(DslValue::as_str),Some(if items.is_empty(){"aggregate"}else{"real"}));if !items.is_empty(){assert_eq!(value.get("value").unwrap().get("bits").and_then(DslValue::as_str),Some(""));}offset+=1;if let Some(members)=items.first().and_then(|child|child["value"].as_array()){for member in members{let control=prepared.control(offset).unwrap();let StagedScalarKind::Text{value}=control.scalar.kind else{panic!("original ARRAY REAL word")};assert_eq!(value,member["value"]["bits"].as_str().unwrap());let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("exact REAL member path")};let selected=DslValue::String("9223372036854775808".into());let StagedFormBorrowedEdit::Set{path,..}=binding.plan(prepared.status(),Some(&selected)).unwrap().last().unwrap()else{panic!("exact member Text edit")};assert_eq!(path.len(),11);assert_eq!(path[2],coordinate.to_string());assert_eq!(path[10],"bits");offset+=2;}}}
   else{let StagedScalarKind::Text{value}=control.scalar.kind else{panic!("original selected scalar word")};let raw=items.first().map_or("",|child|if child["kind"]=="real"{child["value"]["bits"].as_str().unwrap()}else{child["value"].as_str().unwrap()});assert_eq!(value,raw);offset+=1;}
  }
  assert_eq!(offset,prepared.controls());caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();
 }
}
